arguments.argument:
if instance_exists(obj_camera) or instance_exists(obj_salvage_camera) or instance_exists(obj_ballora_camera)
    exit
if global.rightdoor = 1
    exit

if (obj_bonnie2.myroom = 6 and dir = 0)
or (obj_mangle.myroom = 6 and dir = 1)
or (obj_springbonnie.myroom = 5 and dir = 0)
{
    //Plays error sound when Bonnie's "myroom" value is 5 or when Chica's "myroom" value is 6
    sound_play(snd_error)
    exit
}
if image_index = 0 or image_index = 2
{
    if dir = 0 and global.leftlightsbroken = 0
    {
        image_index = 1
        global.rightlights = 0
        global.leftlights = 1
        global.poweruse += 1
        if obj_bonnie.myroom = 2 and global.playleftdoorscaresound = 1
        {
            sound_play(snd_doorscare)
            global.playleftdoorscaresound = 0
        }
        sound_loop(snd_lights)  
    }
     else if dir = 0 and global.leftlightsbroken = 0
    {
        image_index = 1
        global.rightlights = 0
        global.leftlights = 1
        global.poweruse += 1
        if obj_springbonnie.myroom = 4 and global.playleftdoorscaresound = 1
        {
            sound_play(snd_doorscare)
            global.playleftdoorscaresound = 0
        }
        sound_loop(snd_lights)  
    }

    else if dir = 1 and global.rightlightsbroken = 0
    {   
        image_index = 3
        global.leftlights = 0
        global.rightlights = 1
        global.poweruse += 1
        if obj_rockstarfreddy.myroom = 4 and global.playrightdoorscaresound = 1
        {
            sound_play(snd_doorscare)
            global.playrightdoorscaresound = 0
        }
        sound_loop(snd_lights)

    }
    else if dir = 1 and global.rightlightsbroken = 0
    {   
        image_index = 3
        global.leftlights = 0
        global.rightlights = 1
        global.poweruse += 1
        if obj_rockstarfreddy.myroom = 5 and global.playrightdoorscaresound = 1
        {
            sound_play(snd_doorscare)
            global.playrightdoorscaresound = 0
        }
        sound_loop(snd_lights)

    }
       else if dir = 1 and global.rightlightsbroken = 0
    {   
